import{z as s,x as d,o as t,c as A,q as r,j as B,D as l,d as E,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"可用表达式","description":"","frontmatter":{"title":"可用表达式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/available-expr.md","filePath":"cs/available-expr.md","lastUpdated":1791413859000}'),p={name:"cs/available-expr.md"};function c(b,a,D,m,h,u){const o=d("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="可用表达式" tabindex="-1">可用表达式 <a class="header-anchor" href="#可用表达式" aria-label="Permalink to &quot;可用表达式&quot;">​</a></h1><div class="epigraph"><p>表达式 $x\\,\\mathrm{op}\\,y$ 在 $p$ 可用，当从入口到 $p$ 的**每条**路都已算过它，且之后操作数没被改写。汇合是交。</p><footer>—— 据龙书第 9 章整理</footer></div><p>上一课<a href="/cs/reaching-def">到达定义</a>是前向并，回答哪次写还活着。本课不重编号定值。缺口是公共子表达式消除（CSE）要的另一判断：这里能不能<strong>重用</strong>已经算过的 \\(t\\leftarrow a+b\\)，而不必再算。必须所有路都算过，故交汇合；任一操作数被赋值则杀掉。后课指令选择在虚拟名 IR 上盖模板，可用集已尽量把重复运算收掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>e</code> 在块内被计算则 <code>gen</code>；块内对 \\(a\\) 或 \\(b\\) 赋值则 <code>kill</code> 所有含该操作数的表达式。方程：<code>in[B]=\\bigcap_{前驱} out[P]</code>（入口块 <code>in=\\emptyset</code>），<code>out[B]=gen[B]\\cup(in[B]-kill[B])</code>。从「全集合」或小心的初值迭代，交保证低估可用——少优化、不错。缺口是交与「表达式」对象，不是再写到达的并。</p><p>与活跃：活跃后向；可用前向交。三套（活跃、到达、可用）够用到分配前；框架同一，格与方向不同。</p><h3 id="可用不是-dag-里「看见过」" tabindex="-1">可用不是 DAG 里「看见过」 <a class="header-anchor" href="#可用不是-dag-里「看见过」" aria-label="Permalink to &quot;可用不是 DAG 里「看见过」&quot;">​</a></h3><p>块内 DAG 只消块内重复。全局可用才能消跨块 CSE。不要把块内哈希当全局可用。</p><p><span class="marginnote">龙书 9.2.6 节。Appel 用可用做 CSE。代数恒等（\\(a+0\\)）是窥孔或另一格，本课只认字面同一 \\(a\\,\\mathrm{op}\\,b\\)。</span></p><p><span class="marginnote">直觉类比：汇合取交像核实「每条路径都能作证」——几个前驱就是几个证人，只要有一个说没见过 \\(a+b\\)，就不能当它可用。宁可漏掉一次复用（少优化、照样对），也不能错用一次（值算错），所以规则是「都见过才算见过」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>枚举 IR 中出现过的表达式为全集的元素。算 gen/kill。交迭代。改写：若 \\(a+b\\) 在指令前可用，换成对已有临时的拷贝，再交给拷贝传播。</p>',12)),(t(),B(n,null,{default:l(()=>[i(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXPR%5B%22%E8%A1%A8%E8%BE%BE%E5%BC%8F%E5%85%A8%E9%9B%86%22%5D%20--%3E%20GK%5B%22gen%20%2F%20kill%20%E6%93%8D%E4%BD%9C%E6%95%B0%22%5D%0A%20%20GK%20--%3E%20MEET%5B%22%E5%89%8D%E5%90%91%E4%BA%A4%22%5D%0A%20%20MEET%20--%3E%20CSE%5B%22%E6%9B%BF%E6%8D%A2%E4%B8%BA%E5%B7%B2%E6%9C%89%E4%B8%B4%E6%97%B6%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"关键边：若只在部分前驱可用，可在其他前驱补算再交——那是 PRE（部分冗余），本课点名不写完。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("kill 必须随赋值精确："),e("code",null,"a"),E(" 被写掉则 \\(a+b\\)、\\(c+a\\) 都死。别名保守：可能改到 \\(a\\) 则杀，可用变少。SSA 上操作数是名，杀更干净。不要在浮点上随便 CSE 掉含舍入的重复，若语言允许收缩；本课整数 IR 默认可消。")],-1)),a[6]||(a[6]=e("p",null,[E("与"),e("a",{href:"/cs/reaching-def"},"到达"),E("：到达告诉你 \\(a\\) 来自哪次写；可用告诉你 \\(a+b\\) 这个运算本身是否还在。二者常一起用。")],-1)),(t(),B(n,null,{default:l(()=>[i(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%88%B0%E8%BE%BE%E7%82%B9%20p%2C%20%E6%83%B3%E9%87%8D%E7%94%A8%20a%2Bb%22%5D%20--%3E%20Q1%7B%22%E4%BB%8E%E5%85%A5%E5%8F%A3%E5%88%B0%20p%20%E7%9A%84%E6%AF%8F%E6%9D%A1%E8%B7%AF%E5%BE%84%E9%83%BD%E7%AE%97%E8%BF%87%20a%2Bb%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%9F%90%E6%9D%A1%E8%B7%AF%E6%B2%A1%E7%AE%97%E8%BF%87%22%7C%20NO%5B%22%E4%B8%8D%E5%9C%A8%E5%8F%AF%E7%94%A8%E9%9B%86%2C%20%E4%B8%8D%E8%AE%B8%E9%87%8D%E7%94%A8%22%5D%0A%20%20Q1%20--%3E%7C%22%E6%AF%8F%E6%9D%A1%E9%83%BD%E7%AE%97%E8%BF%87%22%7C%20Q2%7B%22%E6%AD%A4%E5%90%8E%20a%20%E6%88%96%20b%20%E8%A2%AB%E6%94%B9%E5%86%99%E8%BF%87%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E4%BB%BB%E4%B8%80%E6%93%8D%E4%BD%9C%E6%95%B0%E8%A2%AB%E5%86%99%22%7C%20KILL%5B%22%E8%A1%A8%E8%BE%BE%E5%BC%8F%E8%A2%AB%E6%9D%80%2C%20%E4%B8%8D%E8%AE%B8%E9%87%8D%E7%94%A8%22%5D%0A%20%20Q2%20--%3E%7C%22%E4%B8%A4%E4%B8%AA%E6%93%8D%E4%BD%9C%E6%95%B0%E5%8E%9F%E6%A0%B7%22%7C%20YES%5B%22a%2Bb%20%E5%8F%AF%E7%94%A8%2C%20%E6%8D%A2%E6%88%90%E8%AF%BB%E5%B7%B2%E6%9C%89%E4%B8%B4%E6%97%B6%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：全集 \\(\\{a+b,\\ c-d,\\ a\\times 2\\}\\)，某块 gen 了 \\(a+b\\) 又对 \\(c\\) 赋值，则 \\(c-d\\) 被杀，该块 out \\(= \\{a+b\\}\\)；若两个前驱的 out 分别是 \\(\\{a+b\\}\\) 与 \\(\\{a+b,\\ a\\times 2\\}\\)，本块 in 取交后只剩 \\(\\{a+b\\}\\)——少的那一项就是「有的路没见过」。</span></p><p><span class="marginnote">常见误区：初学者容易以为「数学上相等就能复用」。本课只认字面同一的 \\(a\\,\\mathrm{op}\\,b\\)：\\(a+b\\) 与 \\(b+a\\) 不算同一个；浮点更危险，若语言允许把 \\(a+b+c\\) 收缩成融合运算，随手复用可能改变舍入结果。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不选机器指令、不着色。不把循环不变外提写完（那要支配与回边，可用是零件）。后课默认：全局 CSE 按可用表达式做。指令选择把剩下的运算变成 ISA 模板。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可用：前向、交；操作数被写则杀。</li><li>用于全局 CSE；块内 DAG 不够跨块。</li><li>低估可用才安全。</li><li>出处：Aho et al., 龙书第 9 章。</li></ul>',6))])}const F=s(p,[["render",c]]);export{f as __pageData,F as default};
